import os
from typing import Any, Dict, List, Optional

import boto3
from botocore.exceptions import BotoCoreError, ClientError


def _safe_text(value: Any) -> Optional[str]:
    if value is None:
        return None
    if isinstance(value, str):
        return value.strip() or None
    return str(value)


def _safe_float(value: Any) -> Optional[float]:
    if value is None:
        return None
    if isinstance(value, (int, float)):
        return float(value)
    try:
        text = str(value).replace(",", "").strip()
        return float(text) if text else None
    except (TypeError, ValueError):
        return None


def _extract_summary_fields(summary_fields: List[Dict[str, Any]]) -> Dict[str, Any]:
    field_map: Dict[str, Any] = {}
    for field in summary_fields or []:
        key = _safe_text(field.get("Type", {}).get("Text")) or _safe_text(field.get("Type", {}).get("Value"))
        value = field.get("ValueDetection", {}) or {}
        text = _safe_text(value.get("Text"))
        if key:
            field_map[key] = text
    return field_map


def _normalize_expense_document(expense_doc: Dict[str, Any]) -> Dict[str, Any]:
    summary_fields = expense_doc.get("SummaryFields", []) or []
    line_items = expense_doc.get("LineItemGroups", []) or []

    summary_map = _extract_summary_fields(summary_fields)

    vendor_name = (
        summary_map.get("VENDOR_NAME")
        or summary_map.get("SUPPLIER_NAME")
        or summary_map.get("RECEIVER_NAME")
    )
    invoice_number = summary_map.get("INVOICE_RECEIPT_ID") or summary_map.get("INVOICE_ID")
    currency = summary_map.get("CURRENCY")
    invoice_date = summary_map.get("INVOICE_RECEIPT_DATE") or summary_map.get("START_DATE")
    due_date = summary_map.get("DUE_DATE")
    tax_amount = _safe_float(summary_map.get("TAX") or summary_map.get("TAX_AMOUNT"))
    subtotal = _safe_float(summary_map.get("SUBTOTAL"))
    total = _safe_float(summary_map.get("TOTAL") or summary_map.get("AMOUNT_DUE") or summary_map.get("AMOUNT_PAID"))
    confidence_values = []

    for field in summary_fields:
        conf = field.get("ValueDetection", {}).get("Confidence")
        if isinstance(conf, (int, float)):
            confidence_values.append(float(conf))

    items = []
    for group in line_items:
        for item in group.get("LineItems", []) or []:
            item_map = {}
            for field in item.get("LineItemExpenseFields", []) or []:
                key = _safe_text(field.get("Type", {}).get("Text")) or _safe_text(field.get("Type", {}).get("Value"))
                value = field.get("ValueDetection", {}) or {}
                if key:
                    item_map[key] = _safe_text(value.get("Text"))
            items.append(
                {
                    "description": item_map.get("ITEM"),
                    "quantity": _safe_float(item_map.get("QUANTITY")),
                    "unit_price": _safe_float(item_map.get("PRICE") or item_map.get("UNIT_PRICE")),
                    "amount": _safe_float(item_map.get("AMOUNT") or item_map.get("TOTAL")),
                    "currency": currency,
                }
            )

    return {
        "vendor_name": vendor_name,
        "invoice_number": invoice_number,
        "invoice_date": invoice_date,
        "due_date": due_date,
        "currency": currency,
        "subtotal": subtotal,
        "tax_amount": tax_amount,
        "total": total,
        "items": items,
        "confidence": round(sum(confidence_values) / len(confidence_values), 2) if confidence_values else None,
        "raw_fields": summary_map,
    }


def normalize_expense_fields(document_bytes: bytes, mime_type: str = "application/pdf") -> Dict[str, Any]:
    """
    Normalize expense fields extracted by Amazon Textract AnalyzeExpense into a standard JSON schema.
    Requires AWS credentials in the environment or configured boto3 session.
    """
    textract = boto3.client("textract")
    try:
        response = textract.analyze_expense(Document={"Bytes": document_bytes})
    except (BotoCoreError, ClientError) as exc:
        raise RuntimeError(f"Textract AnalyzeExpense failed: {exc}") from exc

    expense_documents = response.get("ExpenseDocuments", []) or []
    normalized = [_normalize_expense_document(doc) for doc in expense_documents]

    return {
        "provider": "amazon-textract",
        "operation": "AnalyzeExpense",
        "mime_type": mime_type,
        "documents": normalized,
    }
